mapper.select:
SELECT uvp.user_id,s.name,uvp.update_time,uvp.video_id FROM gc_user_video_play AS uvp LEFT JOIN gc_video AS v ON v.id = uvp.video_id LEFT JOIN gc_subject AS s ON s.id = v.sub_id WHERE uvp.user_id IN
#{userId}
ORDER BY uvp.update_time DESC

SELECT COUNT( v.sub_id ) AS watchNum, TO_CHAR(uvp.create_time, 'YYYY-MM-DD') AS create_time FROM gc_user_video_play uvp LEFT JOIN gc_video v ON uvp.video_id = v.id LEFT JOIN gc_subject s ON v.sub_id = s.id WHERE uvp.user_id IN
#{userId}
AND s.sub_id IN
#{subId}
AND uvp.master_id = #{masterId}
AND TO_CHAR(uvp.create_time, 'YYYY-MM-DD') >= #{startTime} AND TO_CHAR(uvp.create_time, 'YYYY-MM-DD') <= #{endTime} GROUP BY TO_CHAR(uvp.create_time, 'YYYY-MM-DD')

SELECT COUNT(*) AS watchedNum,a.user_id FROM ( SELECT COUNT( uvp.user_id ) AS watchNum ,uvp.user_id,uvp.video_id FROM gc_user_video_play uvp LEFT JOIN gc_video v ON uvp.video_id = v.id LEFT JOIN gc_subject s ON v.sub_id = s.id WHERE uvp.user_id IN
#{userId}
AND s.sub_id IN
#{subId}
AND uvp.master_id = #{masterId} GROUP BY uvp.user_id ,uvp.video_id) as a GROUP BY a.user_id

SELECT s.sub_id as id FROM gc_subject s LEFT JOIN gc_video v ON v.sub_id = s.id LEFT JOIN gc_user_video_play uvp ON uvp.video_id = v.id WHERE uvp.master_id = #{masterId} AND s.sub_id IN
#{subId}
AND uvp.user_id = #{userId} GROUP BY s.sub_id

SELECT count( video_id ),user_id,video_id,master_id FROM gc_user_video_play WHERE video_id IN
#{vid}
AND master_id = #{masterId} AND user_id = #{userId} GROUP BY video_id, user_id, master_id

SELECT SUBJECT_ID, t.VIDEO_ID, t.MASTER_ID, t.USER_ID, MAX(PLAY_STATE) AS PLAY_STATE FROM ( SELECT S.ID AS SUBJECT_ID, P.VIDEO_ID, P.MASTER_ID, P.USER_ID, P.PLAY_STATE FROM GC_USER_VIDEO_PLAY P LEFT JOIN GC_VIDEO V ON P.VIDEO_ID = V.ID LEFT JOIN GC_SUBJECT S ON V.SUB_ID = S.ID WHERE P.USER_ID=#{userId} AND S.ID IN
#{id}
GROUP BY S.ID, P.VIDEO_ID, P.MASTER_ID, P.USER_ID, P.PLAY_STATE ) T GROUP BY SUBJECT_ID, T.VIDEO_ID, T.MASTER_ID, T.USER_ID

SELECT VIDEO_ID AS "videoId", MASTER_ID as "masterId", USER_ID as "userId", MAX(PLAY_STATE) AS "playState", MAX(minTime) as "updateTime" FROM (SELECT P.VIDEO_ID, P.MASTER_ID, P.USER_ID, max(P.PLAY_STATE) as PLAY_STATE, MIN(case when P.play_state=1 then P.update_time end) as minTime FROM GC_USER_VIDEO_PLAY P WHERE 1=1
and P.USER_ID=#{userId}
and P.master_id=#{masterId}
AND P.VIDEO_ID IN
#{videoId}
GROUP BY P.VIDEO_ID, P.MASTER_ID, P.USER_ID, P.PLAY_STATE) t GROUP BY VIDEO_ID, MASTER_ID, USER_ID

SELECT
g.video_id from gc_user_video_play g where g.master_id=#{masterId}
and g.user_id in

    #{ids}

select sub_id as subId,video_id as videoId,MAX(update_time) from (SELECT distinct s0.id as sub_id,vp.video_id, vp.update_time as update_time FROM gc_user_video_play vp LEFT JOIN gc_video v ON v.id = vp.video_id LEFT JOIN gc_subject s1 ON v.sub_id = s1.id LEFT JOIN gc_subject s0 ON s1.fid = s0.id where vp.user_id = #{userId} and s0.id in
#{list}
and vp.master_id = #{masterId} order by vp.update_time desc) as b GROUP BY b.sub_id

SELECT s.id as id FROM gc_subject s LEFT JOIN gc_video v ON v.sub_id = s.id LEFT JOIN gc_user_video_play uvp ON uvp.video_id = v.id WHERE uvp.master_id = #{masterId} AND (s.sub_id IN
#{subId}
or s.id IN
#{subId}
) AND uvp.user_id = #{userId} GROUP BY s.id

SELECT VIDEO_ID AS "videoId", MASTER_ID as "masterId", USER_ID as "userId", MAX(PLAY_STATE) AS "playState" FROM (SELECT P.VIDEO_ID, P.MASTER_ID, P.USER_ID, P.PLAY_STATE FROM GC_USER_VIDEO_PLAY P WHERE 1=1
and P.USER_ID in
#{userIdList}
and P.master_id=#{masterId} AND P.VIDEO_ID IN
#{videoId}
GROUP BY P.VIDEO_ID, P.MASTER_ID, P.USER_ID, P.PLAY_STATE) t GROUP BY VIDEO_ID, MASTER_ID, USER_ID

SELECT userId, SUM( playTime ) as PlayTime FROM ( SELECT vp.user_id userId, end_time - start_time playTime FROM gc_user_video_plays_node vpn LEFT JOIN gc_user_video_play vp ON vp.id = vpn.videoplay_id WHERE end_time - start_time > 0 and vp.video_id in
#{videoId}
) a GROUP BY a.userid

SELECT s.id as subjectId ,p.user_id as userId,p.video_id as videoId from GC_USER_VIDEO_PLAY p left join gc_video v on v.id = p.video_id left join gc_subject s on v.sub_id = s.id where 1=1 and p.master_id=#{masterId}
AND P.VIDEO_ID IN
#{videoId}
and p.USER_ID in
#{userList}
group by s.id,p.user_id

select count(*) as countNum,video_id as videoId from GC_USER_VIDEO_PLAY where video_id in
#{videoId}
GROUP BY video_id

select * from gc_user_video_play play
LEFT JOIN gc_video video on video.id = play.video_id
LEFT JOIN gc_subject sub1 on sub1.id = video.sub_id
LEFT JOIN gc_subject sub0 on sub0.id = sub1.fid
where play.play_state=1 and play.user_id=#{userId} and play.master_id=#{masterId}

    and play.video_id=#{videoId}


    and sub0.id=#{sub0Id}


    and sub1.id=#{sub1Id}
